/** @jsxImportSource @motion-canvas/2d/lib */
// Teleport sample for Motion Canvas (Revideo copy is generated by swapping the package names).
import {Circle, Line, makeScene2D, Node, Rect, Txt} from '@motion-canvas/2d';
import {
  all, createRef, easeInOutCubic, tween, easeOutBack, easeOutCubic, linear, loop, sequence, waitFor,
} from '@motion-canvas/core';
import script from '../../../compare/script.json';
import {CAPS} from '../flags';

const INK = '#1d1b2e';
const FONT = 'Poppins';

function scene(id: string) {
  return script.scenes.find((s) => s.id === id)!;
}

// word-by-word captions for one scene, always lasts the whole scene
function* captions(view: Node, id: string) {
  const s = scene(id);
  if (!CAPS) { yield* waitFor(s.end - s.start); return; }
  const txt = createRef<Txt>();
  view.add(<Txt ref={txt} y={260} fontFamily={FONT} fontWeight={800} fontSize={92} fill={'#fff'}
    stroke={'#111'} lineWidth={14} strokeFirst text={''} shadowColor={'rgba(0,0,0,.35)'} shadowOffsetY={8} zIndex={100} />);
  let t = s.start;
  for (const w of script.words.filter((w) => w.t >= s.start && w.t < s.end)) {
    yield* waitFor(w.t - t);
    t = w.t;
    txt().text(w.w);
    txt().scale(0.7);
    yield* txt().scale(1, 0.12, easeOutBack);
    t += 0.12;
  }
  yield* waitFor(s.end - t);
}

function character(x: number, y: number, s = 1) {
  const legL = createRef<Line>(), legR = createRef<Line>(), eyes = createRef<Node>(), mouth = createRef<Rect>(), root = createRef<Node>();
  const node = (
    <Node ref={root} x={x} y={y} scale={s}>
      <Rect width={160} height={24} radius={12} y={300} fill={'rgba(0,0,0,.25)'} />
      <Line ref={legL} points={[[-22, 130], [-22, 295]]} stroke={INK} lineWidth={9} lineCap={'round'} />
      <Line ref={legR} points={[[22, 130], [22, 295]]} stroke={INK} lineWidth={9} lineCap={'round'} />
      <Line points={[[-55, 0], [-80, 120]]} stroke={INK} lineWidth={9} lineCap={'round'} />
      <Line points={[[55, 0], [80, 120]]} stroke={INK} lineWidth={9} lineCap={'round'} />
      <Rect width={124} height={200} radius={60} y={50} fill={'#6b42c4'} stroke={INK} lineWidth={8} />
      <Circle size={196} y={-140} fill={'#f5f3fb'} stroke={INK} lineWidth={8} />
      <Rect width={170} height={50} radius={[40, 40, 6, 6]} y={-215} fill={'#3a2a2a'} stroke={INK} lineWidth={6} />
      <Node ref={eyes} y={-135}>
        <Circle x={-32} size={44} fill={'#fff'} stroke={INK} lineWidth={5}><Circle size={16} x={3} fill={INK} /></Circle>
        <Circle x={32} size={44} fill={'#fff'} stroke={INK} lineWidth={5}><Circle size={16} x={3} fill={INK} /></Circle>
      </Node>
      <Rect ref={mouth} y={-82} width={40} height={8} radius={4} fill={INK} />
    </Node>
  );
  function* walk(dx: number, dur: number) {
    const steps = Math.round(dur / 0.25);
    yield* all(
      root().x(root().x() + dx, dur, easeOutCubic),
      sequence(0.25, ...[...Array(steps)].map((_, i) => all(
        legL().rotation(i % 2 ? 18 : -18, 0.25), legR().rotation(i % 2 ? -18 : 18, 0.25),
        root().y(y - 12, 0.125).to(y, 0.125)))),
    );
    yield* all(legL().rotation(0, 0.1), legR().rotation(0, 0.1));
  }
  function* wow() {
    yield* all(mouth().size([26, 30], 0.15), mouth().radius(13, 0.15), eyes().scale(1.25, 0.15));
  }
  return {node, root, walk, wow, mouth, eyes};
}

function booth(x: number, y: number, label: string, s = 1) {
  const door = createRef<Rect>(), glow = createRef<Rect>();
  const back = (
    <Node x={x} y={y} scale={s}>
      <Rect ref={glow} width={300} height={560} radius={50} fill={'#9ff0ff'} opacity={0} shadowBlur={60} shadowColor={'#9ff0ff'} />
      <Rect width={280} height={540} radius={40} fill={'rgba(127,211,255,.35)'} stroke={'#2b4d73'} lineWidth={8} />
      <Rect x={-95} width={18} height={480} radius={9} fill={'rgba(255,255,255,.35)'} />
    </Node>
  );
  const front = (
    <Node x={x} y={y} scale={s}>
      <Rect ref={door} width={280} height={0} y={270} offsetY={1} radius={20} fill={'rgba(159,220,255,.6)'} />
      <Rect y={-300} width={320} height={80} radius={18} fill={'#d5dde8'} stroke={'#2b4d73'} lineWidth={7}>
        <Txt text={label} fontFamily={FONT} fontWeight={800} fontSize={40} fill={'#20344f'} />
      </Rect>
      <Rect y={300} width={340} height={60} radius={14} fill={'#aab4c3'} stroke={'#2b4d73'} lineWidth={7} />
    </Node>
  );
  return {back, front, door, glow};
}

function city(view: Node, night: boolean) {
  view.add(<Rect width={1080} height={1920} fill={night ? '#4a2f72' : '#d6efff'} />);
  if (night) view.add(<Rect width={1080} height={700} y={150} fill={'#b06a8c'} opacity={0.6} />);
  const far = createRef<Node>();
  view.add(<Node ref={far}>{[...Array(9)].map((_, i) => (
    <Rect x={-560 + i * 150} y={300 - (i % 3) * 120} width={130} height={900} fill={night ? '#3b2b63' : '#cfd9e6'}>
      {night && [...Array(12)].map((_, k) => <Rect x={-36 + (k % 3) * 36} y={-400 + Math.floor(k / 3) * 70} width={20} height={30}
        fill={(k * 7 + i) % 4 ? '#ffd27a' : '#4b3a75'} />)}
    </Rect>))}</Node>);
  if (night) {
    view.add(<Circle x={260} y={-720} size={90} fill={'#fff4c9'} />);
    view.add(<Line points={[[-320, -800], [-390, 140]]} stroke={'#ff3b2f'} lineWidth={12} />);
    view.add(<Line points={[[-320, -800], [-250, 140]]} stroke={'#ff3b2f'} lineWidth={12} />);
    [-500, -300, -100].forEach((yy, i) => view.add(<Line points={[[-360 + i * 12, yy], [-280 - i * 12, yy]]} stroke={'#ff3b2f'} lineWidth={10} />));
  }
  const trees = night ? [[300, -260, '#ffb7d5'], [460, -200, '#ff9fc6']] : [[-470, -300, '#7cc95a'], [450, -260, '#6cbb4a']];
  trees.forEach(([tx, ty, c]) => {
    view.add(<Rect x={tx as number} y={(ty as number) + 300} width={26} height={420} fill={'#6b4a3a'} />);
    [[0, 0, 220], [-90, 80, 170], [90, 70, 190], [0, 140, 200]].forEach(([dx, dy, r]) =>
      view.add(<Circle x={(tx as number) + dx} y={(ty as number) + dy} size={r} fill={c as string} />));
  });
  view.add(<Rect y={180} width={1080} height={140} fill={night ? '#6c6080' : '#d9d4cc'} />);
  view.add(<Rect y={600} width={1080} height={720} fill={night ? '#3c3552' : '#7a7a86'} />);
  if (night) [...Array(7)].forEach((_, i) => view.add(<Rect x={-450 + i * 150} y={520} width={90} height={260} fill={'#e8e4f0'} opacity={0.85} />));
  return far;
}

function flash(view: Node) {
  const r = createRef<Rect>();
  view.add(<Rect ref={r} width={1080} height={1920} fill={'#e9fbff'} opacity={0} zIndex={50} />);
  return r;
}

export const counter = makeScene2D(function* (view) {
  const s = scene('counter');
  const num = createRef<Txt>();
  const fmt = (v: number) => Math.floor(v).toLocaleString('en-US');
  const cam = createRef<Node>();
  view.add(<Node ref={cam} scale={1.15}>
    <Rect width={1080} height={1920} fill={'#2a070c'} />
    <Circle size={1400} y={-500} fill={'#5a0d16'} opacity={0.8} />
    <Rect x={-455} width={170} height={1920} fill={'#6a0e1a'} />
    <Rect x={455} width={170} height={1920} fill={'#6a0e1a'} />
    <Rect y={-360} width={700} height={360} radius={24} fill={'#120306'} stroke={'#3a0a10'} lineWidth={10} shadowBlur={80} shadowColor={'rgba(255,40,40,.5)'}>
      <Txt y={-110} text={'TELEPORTS TODAY'} fontFamily={FONT} fontWeight={800} fontSize={48} fill={'#ff5050'} letterSpacing={4} />
      <Txt ref={num} y={10} text={fmt(1204557000)} fontFamily={'monospace'} fontWeight={900} fontSize={100} fill={'#ff2b2b'} shadowBlur={24} shadowColor={'#ff0000'} />
      <Rect y={120} width={620} height={26} fill={'#ffcc00'} />
    </Rect>
    {[...Array(6)].map((_, i) => <Rect x={-430 + i * 172} y={420} width={130} height={250} radius={20} fill={'rgba(127,211,255,.4)'} stroke={'#9fb4c8'} lineWidth={5} />)}
    <Rect y={760} width={1080} height={420} fill={'#120305'} />
  </Node>);
  yield* all(captions(view, 'counter'), tween(3.6, (v) => num().text(fmt(1204557000 + 881 * easeOutCubic(v)))), cam().scale(1, s.end - s.start, easeInOutCubic));
});

export const newyork = makeScene2D(function* (view) {
  const cam = createRef<Node>();
  view.add(<Node ref={cam} />);
  const far = city(cam(), false);
  const b = booth(0, 30, 'NEW YORK');
  const c = character(-640, 0, 0.9);
  cam().add(b.back); cam().add(c.node); cam().add(b.front);
  const fl = flash(view);
  yield* all(
    captions(view, 'newyork'),
    cam().scale(1.18, 4.5, easeInOutCubic),
    far().x(-60, 4.5, linear),
    (function* () {
      yield* c.walk(640, 2.0);
      yield* waitFor(0.3);
      yield* all(b.door().height(540, 0.5, easeInOutCubic), c.wow());
      yield* waitFor(0.5);
      yield* all(fl().opacity(1, 0.2), b.glow().opacity(1, 0.2));
      c.root().opacity(0);
      yield* all(fl().opacity(0, 0.6), b.glow().opacity(0, 0.8));
    })(),
  );
});

export const blueprint = makeScene2D(function* (view) {
  view.add(<Rect width={1080} height={1920} fill={'#0d3e86'} />);
  for (let i = -9; i <= 9; i++) view.add(<Line points={[[i * 60, -960], [i * 60, 960]]} stroke={'rgba(255,255,255,.08)'} lineWidth={2} />);
  for (let i = -16; i <= 16; i++) view.add(<Line points={[[-540, i * 60], [540, i * 60]]} stroke={'rgba(255,255,255,.08)'} lineWidth={2} />);
  [-290, 290].forEach((x, i) => {
    view.add(<Rect x={x} y={150} width={220} height={420} radius={30} stroke={'#dff1ff'} lineWidth={5} />);
    view.add(<Rect x={x} y={-80} width={260} height={50} radius={10} stroke={'#dff1ff'} lineWidth={5} />);
    view.add(<Rect x={x} y={380} width={280} height={44} radius={10} stroke={'#dff1ff'} lineWidth={5} />);
    view.add(<Txt x={x} y={480} text={i ? 'TOKYO' : 'NEW YORK'} fontFamily={FONT} fontWeight={800} fontSize={52} fill={'#eaf6ff'} />);
    view.add(<Txt x={x} y={-130} text={i ? 'PRINTER' : 'SCANNER'} fontFamily={FONT} fontWeight={600} fontSize={26} fill={'#eaf6ff'} />);
  });
  const arc = createRef<Line>(), label = createRef<Txt>(), x = createRef<Node>(), dot = createRef<Circle>();
  view.add(<Line ref={arc} points={[[-290, -100], [0, -900], [290, -100]]} radius={600} stroke={'#7fd9ff'} lineWidth={7} end={0} />);
  view.add(<Line points={[[-180, 190], [0, 60], [180, 190]]} radius={300} stroke={'#dff1ff'} lineWidth={5} lineDash={[22, 18]} opacity={0.7} />);
  view.add(<Txt ref={label} y={-540} text={'DATA ONLY'} fontFamily={FONT} fontWeight={800} fontSize={64} fill={'#eaf6ff'} opacity={0} />);
  view.add(<Circle ref={dot} size={30} fill={'#bff4ff'} opacity={0} />);
  view.add(<Node ref={x} y={120} scale={0}>
    <Line points={[[-60, -60], [60, 60]]} stroke={'#ff4d4d'} lineWidth={22} lineCap={'round'} />
    <Line points={[[60, -60], [-60, 60]]} stroke={'#ff4d4d'} lineWidth={22} lineCap={'round'} />
  </Node>);
  view.add(<Rect y={600} width={800} height={120} stroke={'#dff1ff'} lineWidth={4}>
    <Txt x={-110} text={'TELEPORT MK II · HOW IT WORKS'} fontFamily={FONT} fontSize={30} fill={'#dff1ff'} />
    <Txt x={290} text={'CLASSIFIED'} fontFamily={FONT} fontWeight={800} fontSize={30} fill={'#ff6b6b'} />
  </Rect>);
  const a = character(-290, 160, 0.55), b = character(290, 160, 0.55);
  b.root().opacity(0);
  view.add(a.node); view.add(b.node);
  yield* all(
    captions(view, 'blueprint'),
    (function* () {
      yield* waitFor(0.3);
      dot().opacity(1);
      yield* all(arc().end(1, 1.5, easeInOutCubic), label().opacity(1, 1.5), a.root().opacity(0, 1.5),
        b.root().opacity(1, 1.5), dot().position(() => arc().getPointAtPercentage(arc().end()).position, 0));
      dot().opacity(0);
      yield* waitFor(0.6);
      yield* x().scale(1, 0.35, easeOutBack);
    })(),
  );
});

export const tokyo = makeScene2D(function* (view) {
  const cam = createRef<Node>();
  view.add(<Node ref={cam} scale={1.12} />);
  city(cam(), true);
  const b = booth(0, 30, 'TOKYO');
  const c = character(0, 0, 0.9);
  c.root().opacity(0);
  b.door().height(540);
  cam().add(b.back); cam().add(c.node); cam().add(b.front);
  const fl = flash(view);
  const q = createRef<Txt>();
  view.add(<Txt ref={q} x={300} y={-420} text={'?'} fontFamily={FONT} fontWeight={900} fontSize={150} fill={'#fff'} stroke={'#111'} lineWidth={10} strokeFirst scale={0} />);
  yield* all(
    captions(view, 'tokyo'),
    cam().scale(1, 3.5, easeInOutCubic),
    (function* () {
      yield* waitFor(0.15);
      yield* all(fl().opacity(1, 0.2), b.glow().opacity(0.9, 0.2));
      c.root().opacity(1);
      yield* c.wow();
      yield* all(fl().opacity(0, 0.6), b.glow().opacity(0, 0.6));
      yield* b.door().height(0, 0.5, easeInOutCubic);
      yield* c.walk(220, 1.1);
      yield* q().scale(1, 0.35, easeOutBack);
    })(),
  );
});
